const items = $input.all();
const extraction = items[0]?.json?.extraction || {};
const fieldSchemas = extraction.field_schemas || [];

const schema = {
  type: 'object',
  properties: {
    content_class: { type: 'string', enum: ['primary_document', 'style_element', 'unclassified'] },
    class_confidence: { type: 'number' }
  },
  required: ['content_class', 'class_confidence'],
  additionalProperties: true
};

for (const field of fieldSchemas) {
  const prop = {};
  if (field.type === 'int') prop.type = 'number';
  else if (field.type === 'list') { prop.type = 'array'; prop.items = { type: 'string' }; }
  else if (field.type === 'class' && field.classes) { prop.type = 'string'; prop.enum = field.classes.split(',').map(c => c.trim()); }
  else prop.type = 'string';
  schema.properties[field.name] = prop;
  schema.required.push(field.name);
}

return items.flatMap(item => {
  const url = item.json.url || item.json.source_url || null;
  const isUrl = url && /^https?:\/\/.+/.test(url) && !item.binary;
  if (isUrl) {
    return [{ json: { ...item.json, output_schema: schema, _inputType: 'url', _jinaUrl: 'https://r.jina.ai/' + url }, binary: { data: { mimeType: 'text/x-url', data: '', fileName: url } } }];
  }
  return item.binary ? Object.keys(item.binary).map(key => ({ json: { ...item.json, output_schema: schema }, binary: { data: item.binary[key] } })) : [{ json: { ...item.json, output_schema: schema } }];
});

