// A model whose free daily quota is used up is not called again until the quota resets: its
// images come back as stopped, with no request made. Changing the model in Vision LLM lifts it.
const model = String($('Vision LLM').params.modelName || '');
const row = $input.all().map((i) => i.json).find((r) => r && r.resets_at);
const blocked = !!row && Date.parse(row.resets_at) > Date.now();
return $('Convert Image Format').all().map((img, i) => {
  if (!blocked) return { json: { ...img.json, vision_open: true }, binary: img.binary, pairedItem: { item: i } };
  return { json: { ...img.json, vision_open: false, status: 'stopped', error: {
    code: 'VISION_DAILY_QUOTA', model, quota_limit: Number(row.quota_limit) || null, resets_at: row.resets_at,
    message: 'Not read: the vision model\'s free daily quota is used up until ' + row.resets_at,
  } }, pairedItem: { item: i } };
});

// Only a 429 that names the DAILY quota stops reading. A per-minute 429 waits for the window and
// sends the image again (also when the repeat already succeeds: the minute has just cleared),
// at most 4 times per run. A 503, a schema miss or anything else fails the run as before, with
// the LLM node's own message, so its alert is unchanged.
const failed = $('Image-to-Text').all(1).map((i) => i.json.error).filter(Boolean).pop() || 'Vision request failed';
const res = $input.first().json;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const details = (body && body.error && body.error.details) || [];
const daily = details.flatMap((d) => d.violations || []).find((v) => /PerDay/i.test(v.quotaId || ''));
const delay = parseFloat((details.find((d) => /RetryInfo/.test(d['@type'] || '')) || {}).retryDelay);
if (!daily) {
  if (!String(failed).includes('too many requests') || $runIndex >= 4) throw new Error(failed);
  return [{ json: { retry_after_s: Math.min(Number.isFinite(delay) ? delay : 20, 60) + 1 } }];
}
// The quota day ends when the provider says so. No retry delay means the end is unknown: look
// again in an hour rather than guess the provider's reset time.
const resetsAt = new Date(Date.now() + (Number.isFinite(delay) ? delay : 3600) * 1000).toISOString();
const model = String($('Vision LLM').params.modelName || '');
return [{ json: {
  model, quota_limit: Number(daily.quotaValue) || null, resets_at: resetsAt, quota_id: daily.quotaId, hit_at: new Date().toISOString(),
  status: 'stopped',
  error: { code: 'VISION_DAILY_QUOTA', model, quota_limit: Number(daily.quotaValue) || null, resets_at: resetsAt,
    message: "Not read: the vision model's free daily quota (" + daily.quotaValue + ') is used up until ' + resetsAt },
} }];

// The table write answers with its row; the loop needs the stopped image back. Writing first and
// passing the image on after keeps Return Result the last node, whose items the caller receives.
return $('Classify Vision Error').all();

// The slot nodes answer with the table row; the vision request needs this pass's image back.
const img = $('If Vision Quota Left').first();
return [{ json: img.json, binary: img.binary, pairedItem: { item: 0 } }];
